// Some portions generated by Codex. Actual Workbench UI, not a replacement renderer.
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {query} from './query.mjs';
const require=createRequire(new URL('../../../e2e/package.json',import.meta.url));
const {chromium}=require('@playwright/test');
const [base='http://127.0.0.1:18080',size='100000',out='browser.json']=process.argv.slice(2);
const url=base+'/rdf4j-workbench/repositories/bench/query';
const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium'});
const context=await browser.newContext({viewport:{width:1360,height:900}});
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(String(e)));
let requestBody=null,mime=null,requestStart=null,responseEndMs=null,executionRequests=0;
const isExecution=r=>r.url()===url && r.method()==='POST' && new URLSearchParams(r.postData()||'').get('action')==='exec';
page.on('request',r=>{if(isExecution(r)){executionRequests++;requestBody=r.postData();requestStart=performance.now();}});
page.on('response',r=>{if(isExecution(r.request())){mime=r.headers()['content-type'];}});
page.on('requestfinished',r=>{if(isExecution(r))responseEndMs=performance.now()-requestStart;});
// The optional small-window diagnostic still consumes/counts the full query. Responses are never mocked.
if(size!=='1000000')await page.route(url,async route=>{
 const req=route.request();const params=new URLSearchParams(req.postData()||'');
 if(req.method()==='POST'&&params.get('action')==='exec'){params.set('batch-size',size);await route.continue({postData:params.toString()});}
 else await route.continue();
});
try{
 await page.goto(url,{waitUntil:'networkidle',timeout:60000});
 await page.locator('.CodeMirror').first().waitFor({state:'visible',timeout:30000});
 await page.locator('.CodeMirror').first().evaluate((el,q)=>el.CodeMirror.setValue(q),query);
 await page.locator('#query-options-toggle').click();
 await page.locator('#lmdb-forced-strategy').selectOption('irKernel',{timeout:30000});
 await page.locator('#query-timeout').fill('600');
 await page.locator('#query-options-toggle').click();
 const before=await (await fetch(base+'/bench-metrics')).json();
 await page.evaluate(()=>{
  window.__bench={start:null,firstDomMs:null,firstPaintMs:null,completionMs:null,error:null};
  document.querySelector('#exec').addEventListener('click',()=>{
   const b=window.__bench;b.start=performance.now();
   const observer=new MutationObserver(()=>{
    const row=document.querySelector('#query-results tr[data-query-row-index="0"] td, #query-results .query-result-record dd');
    if(b.firstDomMs===null && row && row.getBoundingClientRect().height>0){
     b.firstDomMs=performance.now()-b.start;
     requestAnimationFrame(()=>requestAnimationFrame(()=>{b.firstPaintMs=performance.now()-b.start;const r=row.getBoundingClientRect();b.firstRowInViewport=r.top<innerHeight&&r.bottom>0;}));
    }
    const mount=document.querySelector('#query-results'),status=mount?.querySelector('.query-result-status');
    const error=mount?.querySelector('.query-result-error');if(error && error.getBoundingClientRect().height>0){b.error=error.textContent;observer.disconnect();return;}
    if(b.firstDomMs!==null && mount.getAttribute('aria-busy')==='false' && document.querySelector('#query-request-id')?.value==='' && status?.textContent.includes('complete')){
     b.completionMs=performance.now()-b.start;b.status=status.textContent;b.navigation=mount.querySelector('.query-result-navigation__label')?.textContent;observer.disconnect();
    }
   });
   observer.observe(document.querySelector('#query-results'),{subtree:true,childList:true,attributes:true,characterData:true});
  },{once:true,capture:true});
 });
 await page.locator('#exec').click();
 await page.waitForFunction(()=>window.__bench && (window.__bench.completionMs!==null || window.__bench.error!==null),{},{timeout:900000});
 const timing=await page.evaluate(()=>({...window.__bench,resourceTimings:performance.getEntriesByType('resource').filter(r=>r.name.includes('/bench/query')).map(r=>({name:r.name,startTime:r.startTime,responseEnd:r.responseEnd,encodedBodySize:r.encodedBodySize,decodedBodySize:r.decodedBodySize}))}));
 assert.equal(timing.error,null);assert.ok(timing.firstPaintMs>0);assert.match(timing.status,/100,000/);assert.match(timing.status,/complete/);
 assert.match(mime,/workbench-query-v2\+ndjson/);
 assert.equal(executionRequests,1);const params=new URLSearchParams(requestBody);assert.equal(params.has('batch-known-total'),false);assert.equal(params.get('query'),query);assert.equal(params.get('lmdb-forced-strategy'),'irKernel');
 const after=await(await fetch(base+'/bench-metrics')).json();
 await page.screenshot({path:out+'.png'});
 const result={mode:'browser',size:Number(size),querySha256:crypto.createHash('sha256').update(query).digest('hex'),...timing,responseEndMs,mime,before,after,errors,browserVersion:browser.version(),url};
 fs.writeFileSync(out,JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}finally{await browser.close();}
